[tool error]
{
  "ok": false,
  "name": "draw_circle",
  "error": {
    "type": "invalid_params",
    "message": "'space' is a required property",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "space": {
          "type": "string",
          "minLength": 1,
          "description": "'model' (design space, US survey feet) or a sheet id/name (paper space, inches), e.g. 'SH-001' or 'C-101'"
        },
        "layer": {
          "type": "string",
          "minLength": 1,
          "description": "layer name; defaults to the current layer"
        },
        "color": {
          "type": "string",
          "description": "override color; omit for ByLayer"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ],
          "description": "override linetype; omit for ByLayer"
        },
        "center": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "[x, y]"
        },
        "radius": {
          "type": "number",
          "exclusiveMinimum": 0
        }
      },
      "required": [
        "space",
        "center",
        "radius"
      ],
      "additionalProperties": false
    },
    "example": {
      "space": "model",
      "center": [
        1250.0,
        980.0
      ],
      "radius": 24.0
    }
  },
  "warnings": []
}

[tool error]
{
  "ok": false,
  "name": "draw_offset",
  "error": {
    "type": "invalid_params",
    "message": "Additional properties are not allowed ('alignments' was unexpected)",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "alignment": {
          "type": "string",
          "minLength": 1
        },
        "offsets": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": [
              "number",
              "string"
            ]
          },
          "description": "offset distances from the alignment, feet, right of the direction of stationing positive; a string may name the side ('12L', '12R'). A 24 ft pavement is [-12, 12]; add [-14, 14] for 2 ft shoulders."
        },
        "station_range": {
          "type": "array",
          "items": {
            "type": [
              "number",
              "string"
            ],
            "description": "display station: feet (1600) or '16+00.00'"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "draw only between these display stations: how a pavement edge stops at an intersection and picks up again on the far leg"
        },
        "layer": {
          "type": "string",
          "minLength": 1
        },
        "color": {
          "type": "string",
          "description": "named CAD color (black, red, yellow, green, cyan, blue, magenta, gray, white) or '#RRGGBB'"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ]
        },
        "replace": {
          "type": "boolean",
          "description": "delete this alignment's previously drawn offsets at the same distances first (default false); with a station_range, only the pieces inside it"
        }
      },
      "required": [
        "offsets"
      ],
      "additionalProperties": false
    },
    "example": {
      "alignment": "ALIGN-1",
      "offsets": [
        -12,
        12
      ],
      "layer": "rd_EP"
    }
  },
  "warnings": []
}

